// Sigil & Spark v3 (2026-11-06, the choice-driven pivot) — the story runtime.
// An episode is a JSON scene graph in Content/PBX/Story/<ep>.json, generated by tools/story/build_story.py from the script.
// The runtime plays its nodes through the director's script queue:
//   say · choice (timed fuse, silence branch) · set/unset/add · rel · if/then/else · goto (autosave) · hub (free walk with
//   hotspots until a condition holds) · pact (a fail-forward QTE) · toast · title · panel · wait · fade · flash · sfx ·
//   music · objective · end (the "Your Codex" screen).
// Conditions: "FLAG", "!FLAG", "rho>=2", "CLUES>=3 && RITE_LIE", "A || B" (&& binds tighter).
// -pbxauto plays a story by itself; -pbxpath=0210 picks the n-th option at each choice (missing digits = 0, silence = 9).
#include "PBX/PBXDirector.h"
#include "PBX/PBXActors.h"
#include "Dom/JsonObject.h"
#include "Dom/JsonValue.h"
#include "Serialization/JsonReader.h"
#include "Serialization/JsonSerializer.h"
#include "Misc/FileHelper.h"
#include "Misc/Paths.h"
#include "Misc/CommandLine.h"
#include "Misc/Parse.h"
#include "Kismet/GameplayStatics.h"
#include "Sound/SoundBase.h"

DEFINE_LOG_CATEGORY_STATIC(LogPBXStory, Log, All);
#define SLOG(Fmt, ...) UE_LOG(LogPBXStory, Display, TEXT(Fmt), ##__VA_ARGS__)

using FJArr = TArray<TSharedPtr<FJsonValue>>;

static FString StoryPath(const FString& Ep) { return FPaths::ProjectContentDir() / TEXT("PBX/Story") / (Ep + TEXT(".json")); }

bool APBXDirector::HasStory(const FString& Ep) const { return !FParse::Param(FCommandLine::Get(), TEXT("pbxold")) && FPaths::FileExists(StoryPath(Ep)); }

bool APBXDirector::LoadStory(const FString& Ep)
{
	FString Txt;
	if (!FFileHelper::LoadFileToString(Txt, *StoryPath(Ep))) { SLOG("[PBXSTORY] missing %s", *StoryPath(Ep)); return false; }
	TSharedPtr<FJsonObject> O; const TSharedRef<TJsonReader<>> R = TJsonReaderFactory<>::Create(Txt);
	if (!FJsonSerializer::Deserialize(R, O) || !O.IsValid()) { SLOG("[PBXSTORY] bad json %s", *Ep); return false; }
	StoryData = O; StoryEp = Ep;
	FString P; if (FParse::Value(FCommandLine::Get(), TEXT("pbxpath="), P)) AutoPath = P;
	return true;
}

// ---------------------------------------------------------------- vars / text / speakers
bool APBXDirector::StoryCond(const FString& C) const
{
	if (C.TrimStartAndEnd().IsEmpty()) return true;
	TArray<FString> Ors; C.ParseIntoArray(Ors, TEXT("||"));
	for (const FString& Or : Ors)
	{
		TArray<FString> Ands; Or.ParseIntoArray(Ands, TEXT("&&")); bool bAll = true;
		for (FString T : Ands)
		{
			T.TrimStartAndEndInline(); const bool bNot = T.StartsWith(TEXT("!")) && !T.StartsWith(TEXT("!=")); if (bNot) T.RightChopInline(1);
			static const TCHAR* Ops[] = { TEXT(">="), TEXT("<="), TEXT("=="), TEXT("!="), TEXT(">"), TEXT("<") };
			int32 Op = -1, At = -1;
			for (int32 k = 0; k < 6; k++) { At = T.Find(Ops[k]); if (At > 0) { Op = k; break; } }
			bool R;
			if (Op < 0) R = SVar(T.TrimStartAndEnd()) != 0;
			else
			{
				const FString L = T.Left(At).TrimStartAndEnd(), Rs = T.Mid(At + FCString::Strlen(Ops[Op])).TrimStartAndEnd();
				const int32 a = SVar(L), b = Rs.IsNumeric() ? FCString::Atoi(*Rs) : SVar(Rs);
				switch (Op) { case 0: R = a >= b; break; case 1: R = a <= b; break; case 2: R = a == b; break; case 3: R = a != b; break; case 4: R = a > b; break; default: R = a < b; }
			}
			if (bNot) R = !R;
			if (!R) { bAll = false; break; }
		}
		if (bAll) return true;
	}
	return false;
}

FString APBXDirector::StoryText(const FString& In) const
{
	FString T = In;
	const bool bMale = !Game || !Game->State || Game->State->bMale;
	T.ReplaceInline(TEXT("{hero}"), bMale ? TEXT("Rook") : TEXT("Vesna"));
	T.ReplaceInline(TEXT("{lad}"), bMale ? TEXT("lad") : TEXT("girl"));
	T.ReplaceInline(TEXT("{he}"), bMale ? TEXT("he") : TEXT("she"));
	static const TCHAR* Sparks[] = { TEXT("your Spark"), TEXT("Cindril"), TEXT("Glublet"), TEXT("Sporrow") };
	T.ReplaceInline(TEXT("{spark}"), Sparks[FMath::Clamp(SVar(TEXT("partner")), 0, 3)]);
	return T;
}

FString APBXDirector::StorySpeaker(const FString& Who, FLinearColor& OutColor) const
{
	OutColor = FLinearColor(1, .82f, .2f);
	if (Who == TEXT("narrator")) { OutColor = FLinearColor(.85f, .82f, .75f); return FString(); }
	if (Who == TEXT("hero")) { OutColor = FLinearColor(.95f, .9f, .8f); return StoryText(TEXT("{hero}")); }
	if (Who == TEXT("spark")) { OutColor = FLinearColor(.75f, .1f, .12f); return StoryText(TEXT("{spark}")) + TEXT(" (writes)"); }
	if (Who == TEXT("codex")) { OutColor = FLinearColor(.6f, .55f, .45f); return TEXT("Codex"); }
	const TSharedPtr<FJsonObject>* Cast_;
	if (StoryData.IsValid() && StoryData->TryGetObjectField(TEXT("cast"), Cast_))
	{
		const TSharedPtr<FJsonObject>* C;
		if ((*Cast_)->TryGetObjectField(Who, C))
		{
			const TArray<TSharedPtr<FJsonValue>>* Col; if ((*C)->TryGetArrayField(TEXT("color"), Col) && Col->Num() >= 3) OutColor = FLinearColor((*Col)[0]->AsNumber(), (*Col)[1]->AsNumber(), (*Col)[2]->AsNumber());
			return (*C)->GetStringField(TEXT("name"));
		}
	}
	return SpeakerName(FName(*Who));
}

FVector APBXDirector::StoryAt(const FString& At) const
{
	// "npc:rho" (where that person stands) · "spot:<id>" (a map spot) · "x,y,z"
	if (At.StartsWith(TEXT("npc:"))) { FString Id = At.Mid(4); if (const TSharedPtr<FJsonObject>* Cast_; StoryData.IsValid() && StoryData->TryGetObjectField(TEXT("cast"), Cast_)) { const TSharedPtr<FJsonObject>* C; if ((*Cast_)->TryGetObjectField(Id, C)) (*C)->TryGetStringField(TEXT("npc"), Id); } if (const TObjectPtr<APBXNPC>* N = NPCs.Find(FName(*Id))) return (*N)->GetActorLocation(); return FVector::ZeroVector; }
	if (At.StartsWith(TEXT("spot:"))) { if (const FPBXSpot* S = Spots.Find(At.Mid(5))) return S->Pos; return FVector::ZeroVector; }
	TArray<FString> P; At.ParseIntoArray(P, TEXT(","));
	return P.Num() >= 3 ? FVector(FCString::Atof(*P[0]), FCString::Atof(*P[1]), FCString::Atof(*P[2])) : FVector::ZeroVector;
}

// ---------------------------------------------------------------- flow
void APBXDirector::StoryBegin(const FString& Ep, const FString& Scene, bool bFromSave)
{
	if (!LoadStory(Ep)) { Toast(TEXT("Story file missing.")); return; }
	bStoryMode = true; AutoChoice = 0;
	const FString Start = Scene.IsEmpty() ? StoryData->GetStringField(TEXT("start")) : Scene;
	if (bFromSave && Game && Game->State) SVars = Game->State->StoryVars; else SVars.Reset();
	if (!bFromSave && Game && Game->State) Game->State->StoryChoices.Reset();
	SLOG("[PBXSTORY] begin %s at %s (%s)", *Ep, *Start, bFromSave ? TEXT("save") : TEXT("new"));
	StoryGoto(Start);
	QStoryPump();
}

void APBXDirector::StoryGoto(const FString& Scene)
{
	const TSharedPtr<FJsonObject>* Scenes; const TSharedPtr<FJsonObject>* S;
	if (!StoryData->TryGetObjectField(TEXT("scenes"), Scenes) || !(*Scenes)->TryGetObjectField(Scene, S)) { SLOG("[PBXSTORY] ERROR no scene %s", *Scene); Toast(TEXT("Missing scene: ") + Scene); return; }
	StoryScene = Scene; SStack.Reset(); HubSpots.Reset(); bHub = false;
	FStoryFrame F; F.Nodes = (*S)->GetArrayField(TEXT("nodes")); SStack.Add(F);
	UI->Chapter = (*S)->GetStringField(TEXT("title"));
	// autosave at the start of every scene: the vars as they were when the scene began (a reload replays the scene)
	if (Game && Game->State) { Game->State->StoryEp = StoryEp; Game->State->StoryScene = Scene; Game->State->StoryVars = SVars; if (!bAuto) SaveNow(false); }
	SLOG("[PBXSTORY] scene %s", *Scene);
}

void APBXDirector::QStoryPump() { Q([this](float) { StoryPump(); return true; }); }

void APBXDirector::StoryPush(const FJArr* Nodes)
{
	if (!Nodes || !Nodes->Num()) return;
	FStoryFrame F; F.Nodes = *Nodes; SStack.Add(F);
}

void APBXDirector::StoryPump()
{
	int32 Guard = 0;
	while (SStack.Num() && Guard++ < 2000)
	{
		FStoryFrame& Fr = SStack.Last();
		if (Fr.I >= Fr.Nodes.Num()) { SStack.Pop(); continue; }
		const TSharedPtr<FJsonObject> N = Fr.Nodes[Fr.I++]->AsObject();
		if (!N.IsValid()) continue;
		FString S; double D = 0;
		// --- instant nodes
		if (N->TryGetStringField(TEXT("set"), S)) { SVars.Add(S, N->HasField(TEXT("v")) ? (int32)N->GetNumberField(TEXT("v")) : 1); continue; }
		if (N->TryGetStringField(TEXT("unset"), S)) { SVars.Remove(S); continue; }
		if (N->TryGetStringField(TEXT("add"), S)) { SVars.Add(S, SVar(S) + (N->HasField(TEXT("v")) ? (int32)N->GetNumberField(TEXT("v")) : 1)); continue; }
		const TSharedPtr<FJsonObject>* Rel;
		if (N->TryGetObjectField(TEXT("rel"), Rel)) { for (const auto& KV : (*Rel)->Values) { const FString K(KV.Key); SVars.Add(K, FMath::Clamp(SVar(K) + (int32)KV.Value->AsNumber(), -5, 5)); } continue; }
		if (N->TryGetStringField(TEXT("toast"), S)) { Toast(StoryText(S)); continue; }
		if (N->TryGetStringField(TEXT("objective"), S)) { UI->Objective = StoryText(S); continue; }
		if (N->TryGetStringField(TEXT("sfx"), S)) { Sfx(*S); continue; }
		if (N->TryGetStringField(TEXT("music"), S)) { Music(*S); MusicHold = 9999.f; continue; }
		bool bB; if (N->TryGetBoolField(TEXT("blanked"), bB)) { ApplyBlanked(bB); continue; }
		if (N->TryGetStringField(TEXT("log"), S)) { SLOG("[PBXSTORY] %s", *S); continue; }
		if (N->TryGetStringField(TEXT("if"), S))
		{
			const FJArr* Br = nullptr; const bool bOk = StoryCond(S);
			N->TryGetArrayField(bOk ? TEXT("then") : TEXT("else"), Br); StoryPush(Br); continue;
		}
		if (N->TryGetStringField(TEXT("goto"), S)) { StoryGoto(S); continue; }
		const TArray<TSharedPtr<FJsonValue>>* Fl;
		if (N->TryGetArrayField(TEXT("flash"), Fl) && Fl->Num() >= 3) { UI->FlashColor = FLinearColor((*Fl)[0]->AsNumber(), (*Fl)[1]->AsNumber(), (*Fl)[2]->AsNumber()); UI->FlashT = 1.2f; continue; }
		// --- nodes that take time: queue them, then come back here
		if (N->TryGetStringField(TEXT("say"), S))
		{
			FLinearColor C; const FString Name = StorySpeaker(S, C); const FString Line = StoryText(N->GetStringField(TEXT("line")));
			FString Vo; N->TryGetStringField(TEXT("vo"), Vo);
			if (!Vo.IsEmpty()) QDo([this, Vo] { if (USoundBase* V = Snd(*Vo)) UGameplayStatics::PlaySound2D(this, V); });
			// QSay shows SpeakerName(Who): pass the resolved name through the "story" speaker slot
			StorySpeakerName = Name; StorySpeakerColor = C;
			QSay({ { FName(TEXT("__story")), Line } });
			LastLine = Name.IsEmpty() ? Line : Name + TEXT(":  ") + Line;
			QStoryPump(); return;
		}
		if (N->TryGetNumberField(TEXT("wait"), D)) { QWait(D); QStoryPump(); return; }
		if (N->TryGetNumberField(TEXT("fade"), D)) { double Secs = .6; N->TryGetNumberField(TEXT("secs"), Secs); QFade(D, Secs); QStoryPump(); return; }
		if (N->TryGetStringField(TEXT("title"), S))
		{
			FString Sub; N->TryGetStringField(TEXT("sub"), Sub); Splash(StoryText(S), StoryText(Sub), 3.2f);
			if (bAuto) { const FString Shot_ = FString::Printf(TEXT("st_%s"), *StoryScene); QDo([this, Shot_] { Shot(Shot_); }); }
			QWait(2.6f); QStoryPump(); return;
		}
		if (N->TryGetStringField(TEXT("panel"), S))
		{
			// drawn close-up panels (P2 makes the art; until then the panel's description is shown as a caption)
			const FString Cap = StoryText(S);
			QDo([this, Cap] { UI->Letterbox = 1.f; UI->Caption = TEXT("~"); UI->CaptionSub = Cap; UI->CaptionA = 1.f; });
			QWait(bAuto ? .8f : 2.4f);
			QDo([this] { UI->Letterbox = 0.f; UI->Caption.Empty(); UI->CaptionSub.Empty(); UI->CaptionA = 0.f; });
			QStoryPump(); return;
		}
		const TSharedPtr<FJsonObject>* Sub;
		if (N->HasField(TEXT("choice"))) { StoryChoice(N); return; }
		if (N->TryGetObjectField(TEXT("pact"), Sub)) { StoryPact(*Sub); return; }
		if (N->TryGetObjectField(TEXT("hub"), Sub))
		{
			Fr.I--;   // a hub stays the current node until its exit condition holds
			if (StoryHub(*Sub)) { Fr.I++; continue; }
			return;
		}
		if (N->HasField(TEXT("end"))) { StoryEndEpisode(); return; }
		SLOG("[PBXSTORY] WARNING unknown node in %s", *StoryScene);
	}
	if (!SStack.Num()) SLOG("[PBXSTORY] story stack empty in %s (no goto / end)", *StoryScene);
}

// ---------------------------------------------------------------- choices
void APBXDirector::StoryChoice(const TSharedPtr<FJsonObject>& N)
{
	const FString Prompt = StoryText(N->GetStringField(TEXT("choice")));
	double T = 0; N->TryGetNumberField(TEXT("t"), T);
	TSharedPtr<TArray<TSharedPtr<FJsonObject>>> Opts = MakeShared<TArray<TSharedPtr<FJsonObject>>>();
	TArray<FPBXOption> UIOpts;
	for (const TSharedPtr<FJsonValue>& V : N->GetArrayField(TEXT("opts")))
	{
		const TSharedPtr<FJsonObject> O = V->AsObject(); FString C; O->TryGetStringField(TEXT("if"), C);
		if (!StoryCond(C)) continue;
		Opts->Add(O);
		FPBXOption X; X.Title = StoryText(O->GetStringField(TEXT("text"))); X.Key = FString::FromInt(Opts->Num());
		FString Hint; if (O->TryGetStringField(TEXT("hint"), Hint)) X.Sub = Hint;
		UIOpts.Add(X);
	}
	FString Id; N->TryGetStringField(TEXT("id"), Id);
	const FString Scene = StoryScene;
	auto Pick = [this, Opts, N, Id, Scene](int32 i)
	{
		CloseChoice(); UI->FuseMax = UI->FuseT = 0.f; UI->bStoryChoice = false; OnFuse = nullptr;
		const FJArr* Do = nullptr; FString Text = TEXT("(silence)");
		if (Opts->IsValidIndex(i)) { (*Opts)[i]->TryGetArrayField(TEXT("do"), Do); Text = (*Opts)[i]->GetStringField(TEXT("text")); }
		else N->TryGetArrayField(TEXT("silent"), Do);
		if (!Id.IsEmpty() && Game && Game->State) Game->State->StoryChoices.Add(Id + TEXT("=") + (Opts->IsValidIndex(i) ? FString::FromInt(i) : TEXT("s")));
		SLOG("[PBXSTORY] choice %s:%s -> %d %s", *Scene, *Id, i, *Text);
		StoryPush(Do); QStoryPump();
	};
	if (UIOpts.Num() == 0) { SLOG("[PBXSTORY] ERROR choice %s with no eligible option", *Id); Pick(-1); return; }
	OpenChoice(TEXT(""), Prompt.IsEmpty() ? LastLine : Prompt, UIOpts, false, Pick);
	UI->bStoryChoice = true;
	if (T > 0) { UI->FuseMax = UI->FuseT = T; OnFuse = [Pick] { Pick(-1); }; }
	if (bAuto)   // the path digit for this choice (9 = let the fuse burn out)
	{
		const int32 Idx = AutoChoice++; int32 k = AutoPath.IsValidIndex(Idx) ? AutoPath[Idx] - '0' : 0;
		if (k == 9 && T <= 0) k = 0;
		if (k != 9) { k = FMath::Clamp(k, 0, UIOpts.Num() - 1); Q([this, Pick, k](float t) { if (t < .6f) return false; Pick(k); return true; }); }
		if (AutoShots < 400) Shot(FString::Printf(TEXT("ch_%s_%02d"), *StoryScene, Idx));
	}
}

void APBXDirector::StoryFuseTick(float Dt)
{
	if (UI->FuseMax <= 0.f || UI->Mode != EPBXUIMode::Choice) return;
	UI->FuseT -= Dt;
	if (UI->FuseT <= 0.f) { UI->FuseT = UI->FuseMax = 0.f; if (OnFuse) { TFunction<void()> F = OnFuse; OnFuse = nullptr; F(); } }
}

// ---------------------------------------------------------------- pact moments (fail forward)
void APBXDirector::StoryPact(const TSharedPtr<FJsonObject>& N)
{
	double Steps = 3, Window = 1.8; N->TryGetNumberField(TEXT("steps"), Steps); N->TryGetNumberField(TEXT("window"), Window);
	FString Prompt = TEXT("WRITE THE GLYPH"); N->TryGetStringField(TEXT("prompt"), Prompt);
	struct FPact { int32 Step = 0, Hits = 0, N = 3; float W = 1.8f, T0 = 0.f; bool bArmed = false; };
	TSharedPtr<FPact> P = MakeShared<FPact>(); P->N = (int32)Steps; P->W = (float)Window;
	const bool bAutoWin = !FParse::Param(FCommandLine::Get(), TEXT("pbxpactfail"));
	Q([this, P, N, Prompt, bAutoWin](float T)
	{
		if (!P->bArmed) { P->bArmed = true; P->T0 = T + .8f; bConfirm = false; UI->Letterbox = 1.f; Sfx(TEXT("ui_page")); }
		const float L = T - P->T0;
		if (L < 0.f) { Splash(Prompt, TEXT("get ready…"), .3f); bConfirm = false; return false; }
		const float W = P->W, Ls = L - P->Step * (W + .35f);
		if (Ls < 0.f) { bConfirm = false; return false; }   // the gap between strokes
		const int32 Left = FMath::CeilToInt(FMath::Max(0.f, W - Ls) * 4.f);
		Splash(FString::Printf(TEXT("[E]  STROKE %d / %d"), P->Step + 1, P->N), FString::ChrN(Left, TEXT('|')), .3f);
		if (bAuto && bAutoWin && Ls > W * .4f) bConfirm = true;
		if (bConfirm || Ls >= W)
		{
			if (bConfirm) { P->Hits++; Sfx(TEXT("sfx_confirm")); UI->FlashColor = FLinearColor(.75f, .1f, .1f); UI->FlashT = .35f; }
			else { UI->ShakeT = .4f; }
			bConfirm = false; P->Step++;
			if (P->Step >= P->N)
			{
				const bool bWin = P->Hits >= P->N - (P->N > 3 ? 1 : 0);   // one miss allowed in long sequences
				UI->Letterbox = 0.f; UI->BigT = 0.f;
				SLOG("[PBXSTORY] pact %s %d/%d -> %s", *StoryScene, P->Hits, P->N, bWin ? TEXT("win") : TEXT("lose"));
				const FJArr* Br = nullptr; N->TryGetArrayField(bWin ? TEXT("win") : TEXT("lose"), Br); StoryPush(Br); QStoryPump();
				return true;
			}
		}
		return false;
	});
}

// ---------------------------------------------------------------- hubs (walk, look, talk)
bool APBXDirector::StoryHub(const TSharedPtr<FJsonObject>& N)
{
	FString Exit; N->TryGetStringField(TEXT("exit"), Exit);
	FString Obj; if (N->TryGetStringField(TEXT("objective"), Obj)) UI->Objective = StoryText(Obj);
	HubSpots.Reset();
	for (const TSharedPtr<FJsonValue>& V : N->GetArrayField(TEXT("spots")))
	{
		const TSharedPtr<FJsonObject> O = V->AsObject(); FString C; O->TryGetStringField(TEXT("if"), C);
		FStorySpot Sp; Sp.Id = O->GetStringField(TEXT("id")); O->TryGetStringField(TEXT("label"), Sp.Label);
		bool bOnce = true; O->TryGetBoolField(TEXT("once"), bOnce); Sp.bOnce = bOnce;
		if (Sp.bOnce && SVar(TEXT("seen.") + Sp.Id)) continue;
		if (!StoryCond(C)) continue;
		Sp.Pos = StoryAt(O->GetStringField(TEXT("at")));
		if (Sp.Pos.IsZero() && Player) Sp.Pos = PlayerLoc() + FVector(200.f * (HubSpots.Num() + 1), 0, 0);   // placeholder until staged
		const FJArr* Do; if (O->TryGetArrayField(TEXT("do"), Do)) Sp.Do = *Do;
		HubSpots.Add(Sp);
	}
	if (StoryCond(Exit) && !Exit.IsEmpty()) { HubSpots.Reset(); bHub = false; UI->Objective.Empty(); return true; }
	if (!HubSpots.Num()) { SLOG("[PBXSTORY] ERROR hub in %s has no spots left and exit '%s' is false", *StoryScene, *Exit); HubSpots.Reset(); bHub = false; return true; }
	bHub = true;
	if (bAuto) QDo([this] { if (bHub && HubSpots.Num()) StoryUseSpot(0); });   // autotest: visit the spots in order
	return false;
}

void APBXDirector::StoryUseSpot(int32 i)
{
	if (!HubSpots.IsValidIndex(i)) return;
	const FStorySpot Sp = HubSpots[i];
	if (Sp.bOnce) SVars.Add(TEXT("seen.") + Sp.Id, 1);
	bHub = false; HubSpots.Reset(); UI->Prompt.Empty();
	SLOG("[PBXSTORY] spot %s:%s", *StoryScene, *Sp.Id);
	StoryPush(&Sp.Do); QStoryPump();
}

// ---------------------------------------------------------------- the end of an episode: "Your Codex"
void APBXDirector::StoryEndEpisode()
{
	SLOG("[PBXSTORY] END %s", *StoryEp);
	TArray<FPBXOption> Pages; TArray<FString> Lines;
	const TArray<TSharedPtr<FJsonValue>>* Codex;
	if (StoryData->TryGetArrayField(TEXT("codex"), Codex))
		for (const TSharedPtr<FJsonValue>& V : *Codex)
		{
			const TSharedPtr<FJsonObject> P = V->AsObject(); FPBXOption X; X.Title = P->GetStringField(TEXT("title")); X.Sub = TEXT("— unwritten —");
			for (const TSharedPtr<FJsonValue>& W : P->GetArrayField(TEXT("pages")))
			{
				const TArray<TSharedPtr<FJsonValue>>& Pr = W->AsArray();
				if (Pr.Num() >= 2 && StoryCond(Pr[0]->AsString())) { X.Sub = Pr[1]->AsString(); break; }
			}
			Lines.Add(X.Title + TEXT(": ") + X.Sub); Pages.Add(X);
		}
	for (const FString& L : Lines) SLOG("[PBXSTORY] codex %s", *L);
	FPBXOption Back; Back.Title = TEXT("Close the book"); Pages.Add(Back);
	if (Game && Game->State) { Game->State->StoryScene = TEXT("__end"); Game->State->StoryVars = SVars; if (!bAuto) SaveNow(false); }
	if (bAuto) { Shot(TEXT("st_your_codex")); QWait(1.5f); QDo([this] { bStoryMode = false; FPlatformMisc::RequestExit(false); }); }
	OpenChoice(TEXT("YOUR CODEX"), TEXT("The pages your choices wrote."), Pages, false, [this, N = Pages.Num()](int32 i)
	{
		if (i == N - 1) { CloseChoice(); bStoryMode = false; ToTitle(); }
	});
}
